UPDATE `tmp_hunter_taming` SET `ID` = 25076, `AllowableRaces` = 16, `RewardNextQuest` = 25077, `StartItem` = 52286, `RequiredItemId1` = 52286, `RequiredItemCount1` = 1,
    `RewardSpell` = 0, `RewardDisplaySpell` = 0, `LogTitle` = 'Taming the Beast',
    `LogDescription` = 'Use the Taming Rod to befriend a Greater Duskbat.',
    `QuestDescription` = 'You have spent your young career mastering the arts of single combat.  I feel it is high time that you learned a new form of combat - that of the trained pet.$b$bTake this rod and use it on a greater duskbat until it joins you and your cause.  It may take you some time, but I have faith that you can bend the bat to your will.',
    `AreaDescription` = 'Tame a Greater Duskbat', `QuestCompletionLog` = 'Return to Dedlow Wormwood at Brill in Tirisfal Glades.', `VerifiedBuild` = 0;
