UPDATE `tmp_hunter_taming` SET `ID` = 25077, `AllowableRaces` = 16, `RewardNextQuest` = 25078, `StartItem` = 52287, `RequiredItemId1` = 52287, `RequiredItemCount1` = 1,
    `RewardSpell` = 0, `RewardDisplaySpell` = 0, `LogTitle` = 'Taming the Beast',
    `LogDescription` = 'Use the Taming Rod to befriend a Plagued Bruin.',
    `QuestDescription` = 'Lately we have seen some young, plagued bears passing over the mountains between here and the plaguelands.  While these bears'' trek into Tirisfal tests and threatens the defenses that we have laid at the Bulwark, their passage is a blessing to us hunters.$b$bProve to me you learned something from our last lesson, and use the rod on a plagued bruin, far to the east.',
    `AreaDescription` = 'Tame a Plagued Bruin', `QuestCompletionLog` = 'Return to Dedlow Wormwood at Brill in Tirisfal Glades.', `VerifiedBuild` = 0;
