UPDATE `tmp_hunter_taming` SET `ID` = 25078, `AllowableRaces` = 16, `RewardNextQuest` = 25083, `StartItem` = 52288, `RequiredItemId1` = 52288, `RequiredItemCount1` = 1,
    `RewardSpell` = 1579, `RewardDisplaySpell` = 23356, `LogTitle` = 'Taming the Beast',
    `LogDescription` = 'Use the Taming Rod to befriend a Cursed Darkhound.',
    `QuestDescription` = 'Your final test is of another kind.  The darkhounds that prowl the fields around Brill are no natural beasts: something fouler than the plague runs in their blood.  The living cannot bend such a creature at all.  We can.$b$bUse the rod on a cursed darkhound, and return to me when it has hunted at your side.',
    `AreaDescription` = 'Tame a Cursed Darkhound', `QuestCompletionLog` = 'Return to Dedlow Wormwood at Brill in Tirisfal Glades.', `VerifiedBuild` = 0;
