UPDATE `tmp_hunter_taming` SET `ID` = 25083, `AllowableRaces` = 16, `RewardItem1` = 0, `RewardAmount1` = 0, `LogTitle` = 'Beast Training',
    `LogDescription` = 'Speak with Apolos in the War Quarter of the Undercity.',
    `QuestDescription` = 'One last thing, $g hunter: huntress;.  You''ll want to speak with Apolos at the Undercity.  He''ll teach you the last few bits of knowledge necessary to care for and train your pet.$b$bYou can find him in the War Quarter.',
    `QuestCompletionLog` = 'Speak with Apolos in the War Quarter of the Undercity.', `VerifiedBuild` = 0;
