UPDATE `tmp_hunter_taming` SET `ID` = 26100, `AllowableRaces` = 1, `RewardNextQuest` = 26101, `StartItem` = 60200, `RequiredItemId1` = 60200, `RequiredItemCount1` = 1,
    `RewardSpell` = 0, `RewardDisplaySpell` = 0, `LogTitle` = 'Taming the Beast',
    `LogDescription` = 'Use the Taming Rod to tame a Stonetusk Boar. Practice your skills, then return the Taming Rod to Benjamin Foxworthy in Goldshire.',
    `QuestDescription` = 'So you want a companion at your side, $n?  Every hunter of Stormwind earns that right the same way: by learning what it is to live and fight beside a beast before choosing one.$b$bWe will start with something stubborn rather than dangerous.  Stonetusk boars root about the fields south of Goldshire, around the Maclure and Stonefield farms.  Take this rod, find a boar and use the rod to tame it.  Fight beside it for a while, then come back to me.',
    `AreaDescription` = 'Tame a Stonetusk Boar', `QuestCompletionLog` = 'Return to Benjamin Foxworthy at Goldshire in Elwynn Forest.', `VerifiedBuild` = 0;
