UPDATE `tmp_hunter_taming` SET `ID` = 26101, `AllowableRaces` = 1, `RewardNextQuest` = 26102, `StartItem` = 60201, `RequiredItemId1` = 60201, `RequiredItemCount1` = 1,
    `RewardSpell` = 0, `RewardDisplaySpell` = 0, `LogTitle` = 'Taming the Beast',
    `LogDescription` = 'Use the Taming Rod to tame a Young Forest Bear. Practice your skills, then return the Taming Rod to Benjamin Foxworthy in Goldshire.',
    `QuestDescription` = 'A boar charges at whatever stands before it.  A bear thinks first, and that makes it both a better ally and a harder beast to win over.$b$bYoung forest bears roam the woods of Elwynn: you will find them east of here, on the way to the Eastvale Logging Camp, and across the river to the south.  Use this rod to tame one and learn how it fights.',
    `AreaDescription` = 'Tame a Young Forest Bear', `QuestCompletionLog` = 'Return to Benjamin Foxworthy at Goldshire in Elwynn Forest.', `VerifiedBuild` = 0;
