UPDATE `tmp_hunter_taming` SET `ID` = 26102, `AllowableRaces` = 1, `RewardNextQuest` = 26103, `StartItem` = 60202, `RequiredItemId1` = 60202, `RequiredItemCount1` = 1,
    `RewardSpell` = 1579, `RewardDisplaySpell` = 23356, `LogTitle` = 'Taming the Beast',
    `LogDescription` = 'Use the Taming Rod to tame a Prowler. Practice your skills, then return the Taming Rod to Benjamin Foxworthy in Goldshire.',
    `QuestDescription` = 'Your last lesson is the wolf.  Prowlers hunt in the east of Elwynn, around the Eastvale Logging Camp and Stone Cairn Lake; they are quick, and they will test you harder than the boar or the bear did.$b$bTake the last rod, tame a prowler, and come back to me when you have hunted beside it.  Then you will be ready to tame a beast without the help of any rod.',
    `AreaDescription` = 'Tame a Prowler', `QuestCompletionLog` = 'Return to Benjamin Foxworthy at Goldshire in Elwynn Forest.', `VerifiedBuild` = 0;
