UPDATE `tmp_hunter_taming` SET `ID` = 26103, `AllowableRaces` = 1, `RewardItem1` = 0, `RewardAmount1` = 0, `LogTitle` = 'Training the Beast',
    `LogDescription` = 'Speak with Karrina Mekenda in Stormwind.',
    `QuestDescription` = 'You can tame a pet now, $n, but taming is only the beginning: you must also learn to train your pet and to care for it.$b$bGo to Stormwind and find Karrina Mekenda.  She keeps company with the hunters of the Dwarven District and knows more about beasts than the rest of us together.  She will teach you what I cannot.$b$bGood hunting, $n.',
    `QuestCompletionLog` = 'Speak with Karrina Mekenda in the Dwarven District of Stormwind.', `VerifiedBuild` = 0;
