INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(25076, 1, 6, 'Have you mastered the duskbat?', 0),
(25077, 1, 6, 'Have you hunted alongside the plagued bruin?', 0),
(25078, 1, 6, 'Have you mastered the darkhound?', 0),
(26100, 1, 6, 'Have you tamed the stonetusk boar yet?', 0),
(26101, 1, 6, 'What do you think of the forest bear, $n?', 0),
(26102, 1, 6, 'Have you hunted beside the prowler?', 0);
