INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(26104, 1, 1, 'Ah, you got my letter, $N. Good - I was beginning to think the kobolds had got you.', 0),
(26105, 1, 1, 'So, the scroll found you. I was not certain you could still read.', 0);
